const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
const money = n => new Intl.NumberFormat('es-AR', { style:'currency', currency:'ARS' }).format((n || 0) / 100);
const date = v => new Date(v.length === 10 ? `${v}T12:00:00` : v).toLocaleString('es-AR', v.length === 10 ? { dateStyle:'medium' } : { dateStyle:'short', timeStyle:'short', timeZone:'America/Argentina/San_Luis' });
const today = () => new Intl.DateTimeFormat('en-CA', { timeZone:'America/Argentina/San_Luis', year:'numeric',month:'2-digit',day:'2-digit' }).format(new Date());
const roles = { superadmin:'Superadministrador',admin:'Administrador',operator:'Operador',viewer:'Consulta' };
const schoolBadge = s => s ? `<span class="school-badge" style="--school-color:${esc(s.color||'#315ded')}">${s.logo ? `<img src="${esc(s.logo)}" alt="Logo ${esc(s.name)}">` : esc(s.name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase())}</span>` : '';
let debtorFilters = { min: '', all: false }, productStatus = 'active', productSupplier = '', selectedProducts = new Set(), evo = { supplier: '', from: '', to: '' }, auditFilters = { action: '', actor: '', from: '', to: '' };
let state = null, page = 'accounts', selected = '', school = '', search = '', productSearch = '', productCategory = '', detail = null, documents = [];
async function api(path, options = {}) {
  const res = await fetch(`/api${path}`, { ...options, headers: { 'Content-Type':'application/json', ...(options.headers || {}) }, body: options.body ? JSON.stringify(options.body) : undefined });
  let data; try { data = await res.json(); } catch { throw new Error('No se pudo leer la respuesta. Revisá la conexión.'); }
  if (!res.ok) throw Object.assign(new Error(data.error || 'No se pudo completar la operación.'), { code: data.code });
  return data;
}
function toast(message) { $('#toast').textContent = message; $('#toast').style.display='block'; setTimeout(() => $('#toast').style.display='none', 4500); }
function applyTheme(settings) {
  document.documentElement.style.setProperty('--accent', settings.color);
  document.documentElement.style.setProperty('--font', { system:'Inter, ui-sans-serif, system-ui, sans-serif',humanist:'"Trebuchet MS", system-ui, sans-serif',serif:'Georgia, serif' }[settings.font] || 'system-ui');
  document.title = `${settings.name} · Cuentas claras`;
}
const field = (name, label, type = 'text', value = '', extra = '') => `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const options = (items, value = '') => items.map(([v,l]) => `<option value="${esc(v)}" ${v === value ? 'selected' : ''}>${esc(l)}</option>`).join('');
const empty = (title, description) => `<div class="empty"><span class="symbol">▤</span><h3>${title}</h3><p>${description}</p></div>`;
function pickerMarkup(id,name,label,placeholder){return `<label>${label}<input id="${id}-search" type="search" autocomplete="off" placeholder="${esc(placeholder)}"><input id="${id}-value" name="${name}" type="hidden"><div id="${id}-results" class="picker-results" role="listbox"></div></label>`;}
function wirePicker(id,items,labelOf,onSelect){
  const input=$(`#${id}-search`),value=$(`#${id}-value`),results=$(`#${id}-results`);
  const draw=()=>{const q=input.value.trim().toLocaleLowerCase('es');const shown=items.filter(x=>labelOf(x).toLocaleLowerCase('es').includes(q)).slice(0,12);results.innerHTML=shown.length?shown.map(x=>`<button type="button" role="option" class="picker-option" data-picker-value="${esc(x.id)}">${esc(labelOf(x))}</button>`).join(''):'<span class="muted picker-empty">No hay coincidencias.</span>';};
  input.oninput=()=>{value.value='';onSelect(null);draw();};input.onfocus=draw;results.onmousedown=e=>{if(e.target.closest('[data-picker-value]'))e.preventDefault();};results.onclick=e=>{const button=e.target.closest('[data-picker-value]');if(!button)return;const item=items.find(x=>x.id===button.dataset.pickerValue);if(!item)return;input.value=labelOf(item);value.value=item.id;results.innerHTML='';onSelect(item);};
  return {set(item){input.value=item?labelOf(item):'';value.value=item?.id||'';results.innerHTML='';onSelect(item);}};
}
const effectiveProductPrice=(product,schoolId)=>state.school_prices.find(p=>p.product_id===product.id&&p.school_id===schoolId)?.price??product.price;
function openDialog(title, content, submit, callback) {
  const d = $('#dialog');
  d.innerHTML = `<button class="ghost close" type="button" data-close aria-label="Cerrar">✕</button><h2>${title}</h2><form>${content}<div class="form-error" role="alert"></div><div class="actions"><button type="button" class="secondary" data-close>Cancelar</button><button type="submit">${submit}</button></div></form>`;
  d.querySelectorAll('[data-close]').forEach(b => b.onclick = () => d.close());
  d.showModal();
  const form = d.querySelector('form'); form.operationId = crypto.randomUUID();
  form.onsubmit = async e => {
    e.preventDefault(); const button = form.querySelector('[type=submit]'); button.disabled = true;
    form.querySelector('.form-error').innerHTML = '';
    try { await callback(Object.fromEntries(new FormData(form)), form); }
    catch (error) { form.querySelector('.form-error').innerHTML = `<p class="error">${esc(error.message)}</p>`; }
    finally { button.disabled = false; }
  };
  return form;
}
async function refresh() {
  state = await api('/data'); applyTheme(state.settings);
  if (selected) detail = await api(`/clients/${selected}`);
  render();
}
function filteredClients() { return state.clients.filter(c => (!school || c.school_id === school) && (!search || `${c.name} ${c.contact}`.toLowerCase().includes(search.toLowerCase()))); }
function render() {
  const u = state.user, canManage = ['superadmin','admin'].includes(u.role), canWrite = u.role !== 'viewer';
  const navigation = [['accounts','◫','Cuentas corrientes'],['debtors','◔','Deudores'],['products','▦','Productos y precios'],...(canManage ? [['suppliers','⚖','Proveedores'],['documents','▤','Documentos'],['audit','☷','Auditoría']] : []),...(canManage ? [['users','♧','Usuarios']] : []),...(u.role === 'superadmin' ? [['settings','◉','Colegios y diseño']] : [])];
  $('#app').innerHTML = `<div class="shell"><aside class="sidebar"><div class="brand"><img src="${esc(state.settings.logo || '/icon.svg')}" alt="">${esc(state.settings.name)}</div><nav>${navigation.map(([p,i,l]) => `<button class="nav ${page === p ? 'active' : ''}" data-page="${p}"><span>${i}</span>${l}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="person"><span class="avatar">${esc(u.name.slice(0,1))}</span><div><strong>${esc(u.name)}</strong><small>${roles[u.role]}</small></div></div><button class="ghost" data-password>Cambiar contraseña</button><button class="ghost" data-logout>Salir de la cuenta ↗</button></div></aside><main class="content"><div class="topbar"><div><strong>Tu gestión, en orden.</strong><br><span class="muted">${new Intl.DateTimeFormat('es-AR',{dateStyle:'full'}).format(new Date())}</span></div>${schoolBadge(state.schools.find(s=>s.id===school))}<select id="school" aria-label="Filtrar colegio"><option value="">Todos mis colegios</option>${options(state.schools.map(s => [s.id,s.name]),school)}</select><button class="ghost mobile-user" data-password aria-label="Cambiar contraseña">Contraseña</button><button class="ghost mobile-user" data-logout aria-label="Cerrar sesión">Salir</button></div>${state.environment === 'development' ? '<div class="banner">Entorno de pruebas · Los movimientos no afectan producción.</div>' : ''}<section id="view"></section><p class="muted print-only">${esc(state.settings.footer)}</p></main></div>`;
  document.querySelectorAll('[data-page]').forEach(b => b.onclick = async () => { page = b.dataset.page; selected = ''; detail = null; search = ''; render(); });
  document.querySelectorAll('[data-logout]').forEach(b => b.onclick = async () => { try { await api('/logout',{method:'POST'}); location.reload(); } catch(e) { toast(e.message); } });
  document.querySelectorAll('[data-password]').forEach(b => b.onclick = passwordDialog);
  $('#school').onchange = e => { school = e.target.value; selected = ''; detail = null; render(); };
  if (page === 'accounts') selected ? renderDetail(canWrite) : renderAccounts(canWrite);
  if (page === 'products') renderProducts(canManage);
  if (page === 'users') renderUsers();
  if (page === 'documents') renderDocuments();
  if (page === 'suppliers') renderSuppliers();
  if (page === 'debtors') renderDebtors();
  if (page === 'audit') renderAudit(0);
  if (page === 'settings') renderSettings();
}
